import{_ as p,a0 as l,w as o,s as r,ao as c,I as t,x as e,a1 as a,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"如何在 Kubernetes 集羣中設置動態 NFS 配置 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Kubernetes 集羣中設置動態 NFS 配置 | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Kubernetes 集羣中設置動態 NFS 配置 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Kubernetes 集羣中設置動態 NFS 配置 | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230605.1 ⭐️⭐️ How to Setup Dynamic NFS Provisioning in Kubernetes Cluster","title":"如何在 Kubernetes 集羣中設置動態 NFS 配置","tag":"202307","desc":""},"relativePath":"202307/20230605.1 ⭐️⭐️ How to Setup Dynamic NFS Provisioning in Kubernetes Cluster.md","filePath":"[post].md"}'),d={name:"202307/20230605.1 ⭐️⭐️ How to Setup Dynamic NFS Provisioning in Kubernetes Cluster.md"};function h(u,s,g,b,k,m){const n=l("Link");return o(),r("div",null,[s[15]||(s[15]=c(`<h1 id="如何在-kubernetes-集羣中設置動態-nfs-配置" tabindex="-1">如何在 Kubernetes 集羣中設置動態 NFS 配置 <a class="header-anchor" href="#如何在-kubernetes-集羣中設置動態-nfs-配置" aria-label="Permalink to “如何在 Kubernetes 集羣中設置動態 NFS 配置”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202307/28/222834togtruhoeuh3gtr1.jpg" alt=""></p><blockquote><p>在這篇文章中，我們將向你展示如何在 Kubernetes（k8s）集羣中設置動態 NFS 配置。</p></blockquote><p>Kubernetes 中的動態 NFS 存儲配置允許你按需自動為 Kubernetes 應用配置和管理 NFS（網絡文件系統）卷。它允許創建持久卷（PV）和持久卷聲明（PVC），而無需手動干預或預配置存儲。</p><p>NFS 配置程序負責動態創建 PV 並將其綁定到 PVC。它與 NFS 服務器交互，為每個 PVC 創建目錄或卷。</p><h3 id="先決條件" tabindex="-1">先決條件 <a class="header-anchor" href="#先決條件" aria-label="Permalink to “先決條件”">​</a></h3><ul><li>預裝 Kubernetes 集羣</li><li>具有 Kubernetes 集羣管理員權限的普通用户</li><li>互聯網連接</li></ul><p>事不宜遲，讓我們深入探討步驟：</p><h3 id="步驟-1、準備-nfs-服務器" tabindex="-1">步驟 1、準備 NFS 服務器 <a class="header-anchor" href="#步驟-1、準備-nfs-服務器" aria-label="Permalink to “步驟 1、準備 NFS 服務器”">​</a></h3><p>就我而言，我將在 Kubernetes 主節點（Ubuntu 22.04）上安裝 NFS 服務器。登錄主節點並運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span>
<span class="line"><span>$ sudo apt install nfs-kernel-server -y</span></span></code></pre></div><p>創建以下文件夾並使用 NFS 共享它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir /opt/dynamic-storage</span></span>
<span class="line"><span>$ sudo chown -R nobody:nogroup /opt/dynamic-storage</span></span>
<span class="line"><span>$ sudo chmod 777 /opt/dynamic-storage</span></span></code></pre></div><p>在 <code>/etc/exports</code> 文件中添加以下條目：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/exports</span></span>
<span class="line"><span>/opt/dynamic-storage 192.168.1.0/24(rw,sync,no_subtree_check)</span></span></code></pre></div><p>保存並關閉文件。</p><p>注意：不要忘記更改導出文件中適合你的部署的網絡。</p><p>要使上述更改生效，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo exportfs -a</span></span>
<span class="line"><span>$ sudo systemctl restart nfs-kernel-server</span></span>
<span class="line"><span>$ sudo systemctl status nfs-kernel-server</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/06/NFS-Service-Status-Kubernetes-Master-Ubuntu.png" alt="NFS-Service-Status-Kubernetes-Master-Ubuntu"></p><p>在工作節點上，使用以下 <code>apt</code> 命令安裝 <code>nfs-common</code> 包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install nfs-common -y</span></span></code></pre></div><h3 id="步驟-2、安裝和配置-nfs-客户端配置程序" tabindex="-1">步驟 2、安裝和配置 NFS 客户端配置程序 <a class="header-anchor" href="#步驟-2、安裝和配置-nfs-客户端配置程序" aria-label="Permalink to “步驟 2、安裝和配置 NFS 客户端配置程序”">​</a></h3><p>NFS 子目錄外部配置程序在 Kubernetes 集羣中部署 NFS 客户端配置程序。配置程序負責動態創建和管理由 NFS 存儲支持的持久卷（PV）和持久卷聲明（PVC）。</p><p>因此，要安裝 NFS 子目錄外部配置程序，首先使用以下命令集安裝 <code>helm</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -fsSL -o get_helm.sh https://raw.githubusercontent.com/helm/helm/main/scripts/get-helm-3</span></span>
<span class="line"><span>$ chmod 700 get_helm.sh</span></span>
<span class="line"><span>$ ./get_helm.sh</span></span></code></pre></div><p>運行以下命令來啓用 <code>helm</code> 倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ helm repo add nfs-subdir-external-provisioner https://kubernetes-sigs.github.io/nfs-subdir-external-provisioner</span></span></code></pre></div><p>使用以下 <code>helm</code> 命令部署配置程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ helm install -n nfs-provisioning --create-namespace nfs-subdir-external-provisioner nfs-subdir-external-provisioner/nfs-subdir-external-provisioner --set nfs.server=192.168.1.139 --set nfs.path=/opt/dynamic-storage</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/06/helm-install-nfs-provisioning-kubernetes-cluster.png" alt="helm-install-nfs-provisioning-kubernetes-cluster"></p><p>上面的 <code>helm</code> 命令將自動創建 <code>nfs-provisioning</code> 命名空間，並安裝 NFS 配置程序的容器莢/部署、名稱為 <code>nfs-client</code> 的存儲類，並將創建所需的 rbac。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl get all -n nfs-provisioning</span></span>
<span class="line"><span>$ kubectl get sc -n nfs-provisioning</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/06/kubectl-get-all-nfs-provisioning-kubernetes-cluster.png" alt="kubectl-get-all-nfs-provisioning-kubernetes-cluster"></p><p>完美，上面的輸出確認了配置程序容器莢和存儲類已成功創建。</p><h3 id="步驟-3、創建持久卷聲明-pvc" tabindex="-1">步驟 3、創建持久卷聲明（PVC） <a class="header-anchor" href="#步驟-3、創建持久卷聲明-pvc" aria-label="Permalink to “步驟 3、創建持久卷聲明（PVC）”">​</a></h3><p>讓我們創建 PVC 來為你的容器莢或部署請求存儲。PVC 將從存儲類 <code>nfs-client</code> 請求特定數量的存儲：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi demo-pvc.yml</span></span>
<span class="line"><span>kind: PersistentVolumeClaim</span></span>
<span class="line"><span>apiVersion: v1</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: demo-claim</span></span>
<span class="line"><span>  namespace: nfs-provisioning</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span>  storageClassName: nfs-client</span></span>
<span class="line"><span>  accessModes:</span></span>
<span class="line"><span>    - ReadWriteMany</span></span>
<span class="line"><span>  resources:</span></span>
<span class="line"><span>    requests:</span></span>
<span class="line"><span>      storage: 10Mi</span></span></code></pre></div><p>保存並關閉文件。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/06/PVC-Yaml-Dynamic-NFS-Kubernetes.png" alt="PVC-Yaml-Dynamic-NFS-Kubernetes"></p><p>運行以下 <code>kubectl</code> 命令以使用上面創建的 YML 文件創建 PVC：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl create -f demo-pvc.yml</span></span></code></pre></div><p>驗證 PVC 和 PV 是否創建：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl get pv,pvc -n nfs-provisioning</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/06/Verify-pv-pvc-dynamic-nfs-kubernetes-cluster.png" alt="Verify-pv-pvc-dynamic-nfs-kubernetes-cluster"></p><p>太好了，上面的輸出表明 PV 和 PVC 創建成功。</p><h3 id="步驟-4、測試並驗證動態-nfs-配置" tabindex="-1">步驟 4、測試並驗證動態 NFS 配置 <a class="header-anchor" href="#步驟-4、測試並驗證動態-nfs-配置" aria-label="Permalink to “步驟 4、測試並驗證動態 NFS 配置”">​</a></h3><p>為了測試和驗證動態 NFS 配置，請使用以下 YML 文件啓動測試容器莢：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi test-pod.yml</span></span>
<span class="line"><span>kind: Pod</span></span>
<span class="line"><span>apiVersion: v1</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: test-pod</span></span>
<span class="line"><span>  namespace: nfs-provisioning</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span>  containers:</span></span>
<span class="line"><span>  - name: test-pod</span></span>
<span class="line"><span>    image: busybox:latest</span></span>
<span class="line"><span>    command:</span></span>
<span class="line"><span>      - &quot;/bin/sh&quot;</span></span>
<span class="line"><span>    args:</span></span>
<span class="line"><span>      - &quot;-c&quot;</span></span>
<span class="line"><span>      - &quot;touch /mnt/SUCCESS &amp;&amp; sleep 600&quot;</span></span>
<span class="line"><span>    volumeMounts:</span></span>
<span class="line"><span>      - name: nfs-pvc</span></span>
<span class="line"><span>        mountPath: &quot;/mnt&quot;</span></span>
<span class="line"><span>  restartPolicy: &quot;Never&quot;</span></span>
<span class="line"><span>  volumes:</span></span>
<span class="line"><span>    - name: nfs-pvc</span></span>
<span class="line"><span>      persistentVolumeClaim:</span></span>
<span class="line"><span>        claimName: demo-claim</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/06/Pod-Yml-Dynamic-NFS-kubernetes.png" alt="Pod-Yml-Dynamic-NFS-kubernetes"></p><p>使用以下 <code>kubectl</code> 命令部署容器莢：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl create -f test-pod.yml</span></span></code></pre></div><p>驗證 <code>test-pod</code> 的狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl get pods -n nfs-provisioning</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/06/Verify-Test-Pod-Using-NFS-Volume-Kubernetes.png" alt="Verify-Test-Pod-Using-NFS-Volume-Kubernetes"></p><p>登錄到容器莢並驗證 NFS 卷是否已安裝。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl exec -it test-pod -n nfs-provisioning /bin/sh</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/06/Access-Dynamic-NFS-Inside-Pod-Kubernetes.png" alt="Access-Dynamic-NFS-Inside-Pod-Kubernetes"></p><p>太棒了，上面容器莢的輸出確認了動態 NFS 卷已安裝且可訪問。</p><p>最後刪除容器莢和 PVC，查看 PV 是否自動刪除。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl delete -f test-pod.yml</span></span>
<span class="line"><span>$ kubectl delete -f demo-pvc.yml</span></span>
<span class="line"><span>$ kubectl get pv,pvc -n  nfs-provisioning</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/06/Delete-Pod-PVC-Dynamic-NFS.png" alt="Delete-Pod-PVC-Dynamic-NFS"></p><p>這就是這篇文章的全部內容，希望對你有所幫助。請隨時在下面的評論部分發表你的疑問和反饋。</p><p><em>（題圖：MJ/75dae36f-ff68-4c63-81e8-281e2c239356）</em></p><hr>`,65)),t("p",null,[s[1]||(s[1]=e("via: ",-1)),a(n,{href:"https://www.linuxtechi.com/dynamic-nfs-provisioning-kubernetes/"},{default:i(()=>[...s[0]||(s[0]=[e("https://www.linuxtechi.com/dynamic-nfs-provisioning-kubernetes/",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=e("作者：",-1)),a(n,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:i(()=>[...s[2]||(s[2]=[e("Pradeep Kumar",-1)])]),_:1}),s[7]||(s[7]=e(" 選題：",-1)),a(n,{href:"https://github.com/lkxed/"},{default:i(()=>[...s[3]||(s[3]=[e("lkxed",-1)])]),_:1}),s[8]||(s[8]=e(" 譯者：",-1)),a(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[e("geekpi",-1)])]),_:1}),s[9]||(s[9]=e(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原創編譯，",-1)),a(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[e("Linux中國",-1)])]),_:1}),s[14]||(s[14]=e(" 榮譽推出",-1))])])}const C=p(d,[["render",h]]);export{v as __pageData,C as default};
